void PaletteNameSetMapHitboxes(PaletteName self, MELMap * _Nonnull map) {
    switch (self) {
    case PaletteName16:
        map->xHitbox = &palette16XHitbox;
        map->yHitbox = &palette16YHitbox;
        break;
    case PaletteNameTokyo:
        map->xHitbox = &paletteTokyoXHitbox;
        map->yHitbox = &paletteTokyoYHitbox;
        break;
    case PaletteNameSpace:
        map->xHitbox = &paletteSpaceXHitbox;
        map->yHitbox = &paletteSpaceYHitbox;
        break;
    case PaletteNameSky:
        map->xHitbox = &paletteSkyXHitbox;
        map->yHitbox = &paletteSkyYHitbox;
        break;
    case PaletteNameClouds:
        map->xHitbox = &paletteCloudsXHitbox;
        map->yHitbox = &paletteCloudsYHitbox;
        break;
    case PaletteNameIntro:
        map->xHitbox = &paletteIntroXHitbox;
        map->yHitbox = &paletteIntroYHitbox;
        break;
    default:
        playdate->system->error("Unsupported palette name: %d", self);
        break;
    }
}

